@dataclass(frozen=True)
class VillagePolicy:
    """마을별 생산 및 배송/보상 정책 데이터 클래스"""

    village_name: str
    item_type: str
    items: List[str]
    origin: str
    logistics_partner: str
    packaging_method: str
    refund_policy: str
    damage_compensation: str
    base_shipping_fee: int
    free_shipping_threshold: int
    description: str


