def compare_evidence_authority(type_a: EvidenceType, type_b: EvidenceType) -> int:
    """두 증빙 유형의 권위 서열을 비교합니다.

    Returns:
        1 if type_a is higher authority than type_b
        0 if equal authority
        -1 if type_b is higher authority than type_a
    """
    rank_a = EVIDENCE_HIERARCHY_RANK.get(type_a, 99)
    rank_b = EVIDENCE_HIERARCHY_RANK.get(type_b, 99)

    if rank_a < rank_b:
        return 1
    elif rank_a > rank_b:
        return -1
    return 0


def check_forbidden_authenticity_phrase(text: str) -> bool:
    """진위 감정 금지 조항(제6조)에 위배되는 금지 의심 표현이 포함되어 있는지 확인합니다.

    금지 발언:
    - 'AI로 만든 것 아닌가요'
    - '색을 칠한 것처럼 보입니다'
    - '사진이 조작된 것 같습니다'
    """
    for phrase in FORBIDDEN_AUTHENTICITY_PHRASES:
        if phrase in text:
            return True
    return False


def format_reverification_request(
    reason: str,
    is_measurement: bool = False,
) -> str:
    """재검증 요청 표준 양식 헬퍼 함수 (제8조, 제14조 준수)

    - 감정 결과가 아닌 '대조 결과'를 근거로 정중하게 제시
    - 고객 의심 표현 배제
    - 계측값 관련 시: 원물 + 계측값 + 주문정보가 한 화면에 1장으로 요청
    """
    if is_measurement:
        return (
            f"확인 결과 {reason}. 번거로우시겠지만 정확한 확인을 위해 "
            "원물, 저울의 계측 표시값, 주문 정보가 한 화면에 함께 보이도록 "
            "사진 1장을 촬영하여 보내주시면 신속히 처리해 드리겠습니다. "
            "원물은 판정 완료 시까지 보관을 부탁드립니다."
        )
    return (
        f"확인 결과 {reason}. 사실 관계 확인을 위해 번거로우시겠지만 "
        "해당 상품의 로트번호와 라벨 표기가 함께 보이도록 사진을 전달해 주시면 "
        "확인 후 정성껏 안내해 드리겠습니다."
    )


