def is_gyodong_unhandled_item(item_name: str) -> bool:
    """해당 품목이 교동마을 영농조합의 미취급 품목(애초에 생산/판매하지 않음)인지 판정합니다."""
    for unhandled in GYODONG_UNHANDLED_ITEMS:
        if unhandled in item_name:
            return True
    return False


def get_crop_disaster_record(date: str) -> Optional[CropDisasterRecord]:
    """특정 일자의 작황·재해 이력 기록을 조회합니다."""
    for record in CROP_DISASTER_RECORDS:
        if record.date == date:
            return record
    return None


def get_crop_disasters_by_crop(crop_query: str) -> List[CropDisasterRecord]:
    """특정 품목(수박, 애플망고, 감자, 하우스감귤 등)이 언급된 작황·재해 기록 목록을 반환합니다."""
    results: List[CropDisasterRecord] = []
    for record in CROP_DISASTER_RECORDS:
        if crop_query in record.target_crops or "(전 농산 품목)" in record.target_crops:
            results.append(record)
    return results


def get_crop_disaster_rule(rule_num: int) -> Optional[str]:
    """작황·재해 기록 확인 기준 7대 규칙 중 지정된 번호의 규칙을 반환합니다 (1~7)."""
    if 1 <= rule_num <= len(CROP_DISASTER_RULES):
        return CROP_DISASTER_RULES[rule_num - 1]
    return None


