def get_logistics_record(date: str) -> Optional[LogisticsCancellationRecord]:
    """특정 일자의 시원배송 결항·집하 이력 기록을 조회합니다."""
    for record in LOGISTICS_CANCELLATION_RECORDS:
        if record.date == date:
            return record
    return None


def get_logistics_rule(rule_num: int) -> Optional[str]:
    """시원배송 결항·집하 기록 확인 기준 7대 규칙 중 지정된 번호의 규칙을 반환합니다 (1~7)."""
    if 1 <= rule_num <= len(LOGISTICS_CONFIRMATION_RULES):
        return LOGISTICS_CONFIRMATION_RULES[rule_num - 1]
    return None


def get_logistics_typhoon_details() -> List[LogisticsCancellationDetail]:
    """6월 초 태풍 구간(2037-06-04 ~ 06-08) 운송편 결항 상세 타임라인 목록을 반환합니다."""
    return list(LOGISTICS_TYPHOON_DETAILS)


def can_change_address_or_cancel_typhoon_period(target_timestamp: str) -> bool:
    """
    6월 초 태풍 구간(06-04~06-08) 특정 시점에 배송지 변경 및 주문 취소가 가능한지 판정합니다.
    - 택배 계약서 제3조 및 제10조: 집하(출고) 전에는 변경·취소 가능, 집하 후에는 절대 불가.
    - 06-05 09:10 송장 번호 생성 이후 결항 구간이라도 06-08 09:00 실제 집하 스캔 전까지는
      '송장만 등록된 집하 전 상태'이므로 배송지 변경 및 주문 취소가 가능함.
    - 06-08 09:00 집하 스캔 이후부터는 출고 완료로 변경·취소 불가.
    """
    clean_ts = target_timestamp.replace(" 종일", " 00:00")
    return clean_ts < "2037-06-08 09:00"


def is_today_logistics_normal() -> bool:
    """오늘(2037-06-30) 기준 시원배송 기상·운송 상태가 정상인지 여부를 반환합니다."""
    today_rec = get_logistics_record("2037-06-30")
    if today_rec and today_rec.logistics_status == "정상":
        return True
    return False





