# ==============================================================================
# 개인정보 보호 판정 헬퍼 함수
# ==============================================================================

def get_privacy_article(article_num: int) -> Optional[PrivacyPolicyArticle]:
    """개인정보 처리방침 특정 조항을 조회합니다."""
    return PRIVACY_POLICY_ARTICLES.get(article_num)


def check_reverse_privacy_query(utterance: str) -> bool:
    """
    고객이 상담사에게 저장된 개인정보를 먼저 읽어달라고 요청(역질문)하는지 감지합니다.
    (제10조 저장정보 역질문 차단 가드레일)
    """
    import re
    patterns = [
        r"(등록된|저장된|거기|제)\s*(주소|주소지|도로명|집주소|전화번호|연락처|번호|이름|성함|나이|생년월일|정보).*(불러|알려|말해|확인해|읽어)\s*(주세요|봐요|줘요|달라|주실래요|주시겠어요|줄래)",
        r"(주소|전화번호|연락처|이름|나이).*(불러|읽어)\s*(주세요|봐요|줘요|달라|주실래요)",
        r"몇\s*살로\s*(되어|저장|등록)",
        r"어디로\s*(되어|저장|등록)",
        r"제\s*(주소|전화번호|이름|정보가)\s*(뭐로|어떻게)",
        r"등록된\s*주소",
        r"저장된\s*주소",
    ]
    for pat in patterns:
        if re.search(pat, utterance):
            return True
    return False


def check_credential_solicitation(utterance: str) -> bool:
    """
    비밀번호나 OTP 등 자격증명을 자발적으로 제공하려 하거나 요구받은 상황을 감지합니다.
    (제13조 자격증명 수집 절대 금지)
    """
    import re
    patterns = [
        r"비밀번호.*(알려|불러|입력|드릴|받아|적어|보내|대신)",
        r"비번.*(알려|불러|입력|드릴|받아|적어|보내|대신)",
        r"(인증번호|OTP|otp).*(알려|불러|입력|드릴|받아|적어|보내|왔는|대신)",
        r"(비밀번호|비번|인증번호|OTP|otp)\s*(요구|수집)",
        r"자격증명",
        r"비번은\s*[^\s]+",
        r"비밀번호는\s*[^\s]+",
        r"otp는\s*[^\s]+",
        r"인증번호는\s*[^\s]+",
        r"비밀번호\s*알려드릴",
        r"비번\s*알려드릴",
        r"비번\s*\d+",
        r"비밀번호\s*\d+",
    ]
    for pat in patterns:
        if re.search(pat, utterance, re.IGNORECASE):
            return True
    return False


def check_cumulative_confirmation_limit(count: int) -> bool:
    """
    예/아니오 단답 확인(스무고개)이 3회 상한에 도달했는지 확인합니다.
    (제11조 누적 확인의 중단)
    """
    return count >= PRIVACY_CUMULATIVE_CONFIRMATION_LIMIT


def validate_refund_account_name(original_payer: str, account_holder: str) -> bool:
    """
    환불 계좌 예금주가 원결제자와 일치하는지 판정합니다.
    (제14조 환불 계좌의 본인 명의 확인)
    """
    if not original_payer or not account_holder:
        return False
    # 공백 제거 후 일치 비교
    clean_payer = original_payer.replace(" ", "")
    clean_holder = account_holder.replace(" ", "")
    return clean_payer == clean_holder


