def get_third_party_privacy_article(article_no: int) -> Optional[ThirdPartyPrivacyArticle]:
    """제3자 정보 보호 조항 특정 조항을 조회합니다."""
    return THIRD_PARTY_PRIVACY_ARTICLES.get(article_no)


def evaluate_third_party_privacy_request(utterance: str) -> Dict[str, Any]:
    """고객 발화가 제3자 개인정보 요구에 해당하는지 판별하고 표준 대응 결과를 반환합니다."""
    import re
    # 1. 공급 농가 개인정보
    if any(kw in utterance for kw in ("농가", "생산자", "농민", "밭주인")) and any(kw in utterance for kw in ("연락처", "전화번호", "번호", "주소", "어디 사", "나이", "가족", "매입가", "단가", "직접 연락")):
        return {
            "category": "FARM",
            "article": 4,
            "disclosable": False,
            "response_text": (
                "고객님, 생산 농가의 개인 연락처, 주소, 나이 등은 사내 제3자 정보 보호 조항 제4조에 따라 제공하지 않는 항목입니다. "
                "농가에 전달을 원하시는 사항을 남겨주시면 조합에서 대신 접수하여 당일 중 또는 늦어도 다음 영업일까지 회신을 중계해 드리겠습니다."
            ),
        }
    # 2. 배송기사 개인 연락처
    if any(kw in utterance for kw in ("기사", "배송기사", "택배기사", "운전원")) and any(kw in utterance for kw in ("연락처", "전화번호", "번호", "휴대폰", "통화", "전화 연결", "근무표")):
        return {
            "category": "DRIVER",
            "article": 5,
            "disclosable": False,
            "response_text": (
                "고객님, 배송기사님의 개인 휴대전화 번호 및 직접 통화 연결은 사내 제3자 정보 보호 조항 제5조에 따라 제공하지 않는 항목입니다. "
                "수령 위치나 시간 등 전달 사항은 배송 메모로 접수해 전달해 드리며, 배송 상태는 택배사 배송 조회를 통해 신속히 안내해 드리겠습니다."
            ),
        }
    # 3. 선물 수령인 개인정보
    if any(kw in utterance for kw in ("수령인", "받는 사람", "받는 분", "선물")) and any(kw in utterance for kw in ("주소", "연락처", "전화번호", "어디로 갔", "불러달라", "알려달라")):
        return {
            "category": "RECIPIENT",
            "article": 6,
            "disclosable": False,
            "response_text": (
                "고객님, 선물 주문 등에서 수령인의 주소와 연락처는 사내 제3자 정보 보호 조항 제6조에 따라 주문자께도 제공하지 않는 항목입니다. "
                "배송 진행 상태에 한해 확인을 도와드리고 있습니다."
            ),
        }
    # 4. 공동구매 참여자 개인정보
    if any(kw in utterance for kw in ("공동구매", "공구")) and any(kw in utterance for kw in ("참여자", "명단", "연락처", "송장", "대리 취소", "대리 환불")):
        return {
            "category": "GROUP_MEMBER",
            "article": 7,
            "disclosable": False,
            "response_text": (
                "고객님, 공동구매 대표자께는 전체 진행 상태 집계만 제공되며, 참여자 개별 성명, 연락처, 송장번호는 제공하지 않는 항목입니다. "
                "참여자 주문의 취소나 변경은 각 참여자 본인 인증을 통해서만 가능합니다."
            ),
        }
    # 5. 대표자/직원 사적 배경
    if any(kw in utterance for kw in ("대표", "조합장", "직원", "이민준", "고길동")) and any(kw in utterance for kw in ("나이", "가족", "학력", "경력", "사적", "집주소", "개인 번호")):
        return {
            "category": "STAFF_BACKGROUND",
            "article": 8,
            "disclosable": False,
            "response_text": (
                "고객님, 사업자정보 공시 항목(상호, 대표자명, 사업자번호, 소재지, 대표번호) 외에 대표자나 직원의 사적 배경 및 개인 연락처는 제공하지 않는 항목입니다."
            ),
        }
    return {"category": "NONE", "article": 0, "disclosable": True, "response_text": ""}


