def get_subscription_article(article_no: int) -> Optional[SubscriptionArticle]:
    """정기배송 약관 특정 조항(1~11)을 조회합니다."""
    return SUBSCRIPTION_TERMS_ARTICLES.get(article_no)


def get_all_subscription_articles() -> List[SubscriptionArticle]:
    """정기배송 약관 전체 11개 조항 목록을 반환합니다."""
    return [SUBSCRIPTION_TERMS_ARTICLES[i] for i in sorted(SUBSCRIPTION_TERMS_ARTICLES.keys())]


def calculate_cutoff_datetime(payment_date: str, holidays: Optional[List[str]] = None) -> str:
    """
    해당 회차 결제일 기준 컷오프 일시(3영업일 전 24시)를 계산합니다 (제3조).
    - 결제일 자체는 계산에 불산입 (제3조 제2항)
    - 영업일: 월~금(공휴일 제외) (제2조 제6호)
    - 반환 포맷: YYYY-MM-DD 24:00 (제4조 제3항 날짜와 시각 명시)
    """
    if holidays is None:
        holidays = []

    curr_date = datetime.strptime(payment_date, "%Y-%m-%d").date()
    business_days_counted = 0

    while business_days_counted < SUBSCRIPTION_CUTOFF_BUSINESS_DAYS:
        curr_date -= timedelta(days=1)
        # 월요일(0) ~ 금요일(4)
        if curr_date.weekday() < 5 and curr_date.strftime("%Y-%m-%d") not in holidays:
            business_days_counted += 1

    return f"{curr_date.strftime('%Y-%m-%d')} 24:00"


def is_before_or_at_cutoff(request_datetime: str, cutoff_datetime: str) -> bool:
    """
    요청 시각이 컷오프(YYYY-MM-DD 24:00) 이전 또는 당일 24:00 정각인지 판정합니다.
    - YYYY-MM-DD 24:00은 YYYY-MM-(DD+1) 00:00:00과 동일합니다.
    """
    cutoff_date_str = cutoff_datetime.split()[0]
    cutoff_boundary = datetime.strptime(cutoff_date_str, "%Y-%m-%d") + timedelta(days=1)

    req_parts = request_datetime.strip().split()
    if len(req_parts) == 1:
        req_dt = datetime.strptime(req_parts[0], "%Y-%m-%d")
    elif req_parts[1] == "24:00":
        req_dt = datetime.strptime(req_parts[0], "%Y-%m-%d") + timedelta(days=1)
    else:
        req_dt = datetime.strptime(f"{req_parts[0]} {req_parts[1]}", "%Y-%m-%d %H:%M")

    return req_dt <= cutoff_boundary


def evaluate_subscription_request(
    request_type: str,
    request_datetime: str,
    payment_date: str,
    shipping_stage: str = "결제전",
    holidays: Optional[List[str]] = None,
) -> Dict[str, Any]:
    """
    정기배송 스킵·해지·변경 요청을 판정 순서 및 매트릭스(제10조, 제11조)에 따라 판정합니다.
    """
    cutoff_dt_str = calculate_cutoff_datetime(payment_date, holidays)
    is_before = is_before_or_at_cutoff(request_datetime, cutoff_dt_str)

    req_key = "변경" if any(w in request_type for w in ["변경", "품목", "수량", "주기"]) else (
        "해지" if "해지" in request_type else "스킵"
    )

    reflected_cycle = "이번 회차" if is_before else "다음 회차"
    matrix_entry = SUBSCRIPTION_DECISION_MATRIX.get(req_key, {})
    decision_summary = matrix_entry.get("before_cutoff" if is_before else "after_cutoff", "")

    # 대안 안내 목록 (컷오프 경과 시 제6조②에 따라 필수 제공)
    applicable_alternatives = []
    if not is_before:
        for alt in SUBSCRIPTION_POST_CUTOFF_ALTERNATIVES:
            available = shipping_stage in alt["available_stages"]
            applicable_alternatives.append({
                "name": alt["name"],
                "condition": alt["condition"],
                "available": available,
            })

    forbidden_warning = (
        SUBSCRIPTION_CANCELLATION_FORBIDDEN_ACTIONS if req_key == "해지" else []
    )

    return {
        "request_type": req_key,
        "payment_date": payment_date,
        "cutoff_datetime": cutoff_dt_str,
        "request_datetime": request_datetime,
        "is_before_cutoff": is_before,
        "reflected_cycle": reflected_cycle,
        "decision_summary": decision_summary,
        "alternatives": applicable_alternatives,
        "forbidden_actions": forbidden_warning,
        "skip_limit_unlimited": True,
        "penalty_fee": 0,
        "refund_remaining": "전액환불" if req_key == "해지" else "미결제",
        "discount_clawback": "소급 반환 없음",
    }


