def calculate_tax_and_vat(product_amount: int, shipping_fee: int) -> Dict[str, Any]:
    """
    미가공 농수산물(면세)과 배송비(과세)의 세액을 분리 산정합니다.
    (제3조: 합산 기재 절대 금지 및 용역분 분리 기재 원칙)
    """
    product_amt = max(0, product_amount)
    shipping_amt = max(0, shipping_fee)
    product_vat = 0  # 미가공 농수산물은 면세 (세액 0원)
    shipping_vat = round(shipping_amt * 0.1)  # 배송비는 용역분이라 부가세 10%

    return {
        "product_amount": product_amt,
        "product_vat": product_vat,
        "product_tax_type": "면세 (세액 0원, 세액란 공란 정상)",
        "shipping_amount": shipping_amt,
        "shipping_vat": shipping_vat,
        "shipping_tax_type": "과세 (용역분 부가세 10%)",
        "total_supply_price": product_amt + shipping_amt,
        "total_vat": shipping_vat,
        "total_payment": product_amt + shipping_amt + shipping_vat,
        "separate_invoice_required": True,
        "combined_entry_forbidden": True,
    }


def evaluate_proof_request(
    payment_method: str,
    actual_amount: int,
    points_used: int = 0,
    coupon_discount: int = 0,
    is_wholesale_business: bool = False,
    split_cash_amount: int = 0,
    split_card_amount: int = 0,
) -> Dict[str, Any]:
    """
    결제수단별 세무 증빙 발행 대상 및 기준액을 판정합니다 (제1조).
    """
    real_payment = max(0, actual_amount)
    # 정가가 아닌 실결제액 기준, 적립금/쿠폰 제외
    effective_base = max(0, real_payment - points_used - coupon_discount)

    if any(m in payment_method for m in ["카드", "신용카드", "체크카드"]):
        return {
            "payment_method": "카드",
            "proof_type": "카드 매출전표",
            "issuable": False,
            "base_amount": effective_base,
            "reason": "카드 매출전표로 증빙 대체. 현금영수증 및 세금계산서 별도 발행 불가 (중복 증빙 방지).",
        }

    if is_wholesale_business or "도매" in payment_method or "사업자" in payment_method:
        return {
            "payment_method": "사업자 거래(도매)",
            "proof_type": "전자세금계산서",
            "issuable": True,
            "base_amount": effective_base,
            "reason": "사업자 도매 거래 조건 충족 시 전자세금계산서 발행 대상.",
        }

    if "분할" in payment_method or (split_cash_amount > 0 and split_card_amount > 0):
        return {
            "payment_method": "분할결제",
            "proof_type": "수단별 분할 처리",
            "issuable": True,
            "cash_amount": split_cash_amount,
            "card_amount": split_card_amount,
            "cash_proof": "현금영수증",
            "card_proof": "카드 매출전표",
            "reason": "현금분만 현금영수증, 카드분은 매출전표로 수단별 분할 처리.",
        }

    if any(m in payment_method for m in ["현금", "계좌", "무통장"]):
        return {
            "payment_method": "현금·계좌이체·무통장입금",
            "proof_type": "현금영수증",
            "issuable": True,
            "base_amount": effective_base,
            "reason": "현금영수증 발행 대상 (§2). 실결제액 기준.",
        }

    return {
        "payment_method": payment_method,
        "proof_type": "해당없음",
        "issuable": False,
        "base_amount": 0,
        "reason": "증빙 발행 대상이 아니거나 미확정 결제수단.",
    }


def evaluate_cash_receipt_request(
    receipt_type: str,
    is_business: bool,
    has_provided_id_number: bool,
    is_before_deadline: bool = True,
) -> Dict[str, Any]:
    """
    현금영수증 발행 요청 요건 및 보안 가드레일을 판정합니다 (제2조).
    """
    if not is_before_deadline:
        return {
            "issuable": False,
            "reason": "거래일이 속한 달의 익월 10일 경과. 조합 자체 발행 불가.",
            "action": "국세청 홈택스 자율 발급 절차 안내",
        }

    # 개인은 지출증빙 가능, 사업자는 소득공제 불가
    if is_business and "소득공제" in receipt_type:
        return {
            "issuable": False,
            "reason": "사업자는 소득공제용으로 요청할 수 없음 (지출증빙용으로만 발행 가능).",
            "action": "지출증빙용 전환 안내",
        }

    if not has_provided_id_number:
        return {
            "issuable": False,
            "reason": "고객이 번호를 제시하기 전에 상담사가 기존 등록 번호를 먼저 읽어주는 행위 절대 금지 (개인정보 보호).",
            "action": "고객에게 번호(휴대폰/현금영수증카드/사업자번호) 제시 요청",
        }

    return {
        "issuable": True,
        "receipt_type": receipt_type,
        "reason": "발행 요건 충족. 주문 조회 → 실결제액 확인 → 발행 처리 → 안내 절차 진행.",
        "post_notice": CASH_RECEIPT_RULES["hometax_reflection"],
    }


def evaluate_tax_invoice_request(
    payment_business_name: str,
    requested_business_name: str,
    has_biz_registration_cert: bool,
    is_before_deadline: bool = True,
    product_price: int = 0,
    shipping_fee: int = 0,
) -> Dict[str, Any]:
    """
    세금계산서 발행 요청 및 면세/과세 분리 요건을 판정합니다 (제3조, 제6조).
    """
    if not is_before_deadline:
        return {
            "issuable": False,
            "verdict": "거절",
            "reason": "거래일 익월 10일 경과 건 소급 발행 불가.",
            "proper_procedure": "국세청 홈택스 자율 발급 절차 안내",
        }

    # 결제 명의와 사업자등록증 명의 불일치 시 거절
    if payment_business_name.strip() != requested_business_name.strip():
        return {
            "issuable": False,
            "verdict": "거절",
            "reason": "실제 결제 사업자와 다른 사업자 명의 요청은 허위 증빙에 해당하여 거절.",
            "proper_procedure": "실제 결제자 명의로 발행받은 뒤 당사자 사이에서 정산 안내, 향후 사업자 거래 시 사전 거래처 등록 안내",
        }

    if not has_biz_registration_cert:
        return {
            "issuable": False,
            "verdict": "보류",
            "reason": "사업자등록증 서류 확인 필수 (채팅상 진술만으로 발행 불가).",
            "proper_procedure": "사업자등록증 제출 요청 (상호, 사업자번호, 대표자명, 업태/종목, 수취 이메일 대조)",
        }

    tax_calc = calculate_tax_and_vat(product_price, shipping_fee)

    return {
        "issuable": True,
        "verdict": "발행 승인",
        "issuance_name": requested_business_name,
        "tax_calculation": tax_calc,
        "turnaround": TAX_INVOICE_RULES["turnaround_days"],
        "notice": TAX_INVOICE_RULES["product_vat_exempt_rule"],
    }


def evaluate_proof_correction(code: str) -> Optional[ProofCorrectionCode]:
    """정정 사유 코드(TX-01 ~ TX-06)의 상세 규칙을 반환합니다."""
    return PROOF_CORRECTION_CODES.get(code.upper())


def check_proof_refusal(user_demand: str) -> Optional[ProofRefusalRule]:
    """
    고객의 요구 발화가 7대 거절 대상에 해당하는지 감지합니다 (제6조).
    """
    demand_lower = user_demand.lower()

    if any(k in demand_lower for k in ["다른 사업자", "타사 명의", "타인 사업자", "회사 명의로 바꿔", "다른 회사 명의"]):
        return PROOF_REFUSAL_RULES[0]
    if any(k in demand_lower for k in ["가공 사업자", "페이퍼컴퍼니", "유령"]):
        return PROOF_REFUSAL_RULES[1]
    if any(k in demand_lower for k in ["개인 결제", "개인 카드로 긁고 사업자", "개인분 사업자"]):
        return PROOF_REFUSAL_RULES[2]
    if any(k in demand_lower for k in ["더 많이", "금액 올려", "부풀려", "많이 적어", "초과 기재"]):
        return PROOF_REFUSAL_RULES[3]
    if any(k in demand_lower for k in ["다른 품목", "품명 바꿔", "비품으로", "사무용품으로"]):
        return PROOF_REFUSAL_RULES[4]
    if any(k in demand_lower for k in ["소급 발행", "지난달 건 소급", "10일 지났는데"]):
        return PROOF_REFUSAL_RULES[5]
    if any(k in demand_lower for k in ["취소된 거래", "취소했는데 증빙", "영수증 그대로", "증빙 그대로", "취소된 주문", "취소한 거래", "증빙 유지"]):
        return PROOF_REFUSAL_RULES[6]

    return None



