def get_pickup_section(section_no: int) -> Optional[FarmPickupSection]:
    """산지 픽업 안내 특정 조항(1~5)을 조회합니다."""
    return FARM_PICKUP_SECTIONS.get(section_no)


def get_all_pickup_sections() -> List[FarmPickupSection]:
    """산지 픽업 안내 전체 1~5번 목록을 반환합니다."""
    return [FARM_PICKUP_SECTIONS[i] for i in sorted(FARM_PICKUP_SECTIONS.keys())]


def evaluate_pickup_eligibility(
    is_reserved: bool,
    reservation_days_in_advance: int = 1,
    location_type: str = "집하장",
    time_slot: str = "오전",
    payment_method: str = "온라인몰",
    is_orderer: bool = True,
    has_order_number: bool = True,
    is_designated_proxy: bool = False,
) -> Dict[str, Any]:
    """
    산지 픽업 요건 및 수령 자격을 평가합니다 (§1, §2).
    """
    reasons = []
    eligible = True

    # 1. 사전 예약 필수
    if not is_reserved:
        eligible = False
        reasons.append("사전 예약 필수 (예약 없는 현장 즉석 방문 수령 불가)")

    # 2. 예약 마감 (1영업일 전)
    if reservation_days_in_advance < 1:
        eligible = False
        reasons.append("예약 마감 기한 미준수 (수령 희망일 1영업일 전까지 예약 필수)")

    # 3. 장소 확인 (집하장 1곳만 허용, 밭/하우스 불가)
    if any(loc in location_type for loc in ["밭", "비닐하우스", "하우스", "농가"]):
        eligible = False
        reasons.append("개별 밭이나 비닐하우스 방문 수령 불가 (조합 지정 집하장 1곳 한정)")

    # 4. 시간 확인 (택배 집하·상차 시간대 미운영)
    if any(ts in time_slot for ts in ["오후", "상차", "집하시간", "택배집하"]):
        eligible = False
        reasons.append("택배 집하·상차 시간대 미운영 (물량 혼재 방지 목적, 영업일 오전 지정 시간 한정)")

    # 5. 결제 확인 (온라인몰 사전 결제 한정, 현장 결제 불가)
    if any(pay in payment_method for pay in ["현장", "현금", "현장카드"]):
        eligible = False
        reasons.append("현장 결제 및 현장 주문 불가 (온라인몰 사전 결제 주문 한정)")

    # 6. 본인확인 및 대리 수령
    if not has_order_number:
        eligible = False
        reasons.append("주문번호 확인 불가 (주문번호 + 명의 확인 필수)")

    if not is_orderer and not is_designated_proxy:
        eligible = False
        reasons.append("본인 또는 사전 지정 대리인 아님 (이름/연락처 구술만으로 물품 인도 불가)")

    return {
        "eligible": eligible,
        "reasons": reasons,
        "shipping_fee": PICKUP_SHIPPING_FEE,
        "location_rule": PICKUP_LOCATION_RULE,
        "guide_script": PICKUP_GUIDE_SCRIPT,
    }


def evaluate_pickup_temp_claim(timing: str) -> Dict[str, Any]:
    """
    산지 픽업 물품의 온도 관리 책임 및 하자 접수 가능 여부를 판정합니다 (§3).
    - timing: '인수전', '인수후', '차량적재후', '이동중', '귀가후'
    """
    if timing in ["인수전", "보관중"]:
        return {
            "acceptable": True,
            "responsible_party": "조합",
            "reason": "인수 전 구간은 조합의 지정 보관 상태 유지 책임입니다.",
        }
    else:
        return {
            "acceptable": False,
            "responsible_party": "고객",
            "reason": "인수 시점이 책임 경계이며, 차량에 실은 뒤의 이동 중 온도 관리 및 품온 상승은 하자 사유로 미인정/접수 불가합니다.",
        }


# ==============================================================================
# 17. 공식 상세페이지 판매 상품 3종 (SKU 정의 및 판정)
# ==============================================================================

@dataclass(frozen=True)
class OfficialProductSKU:
    """공식 판매 상품 SKU 명세"""

    sku: str
    name: str
    price: int
    shipping_fee: int
    spec_description: str
    weight_kg: float
    is_min_spec: bool  # True이면 '8kg 이상' 등 규격 상품으로 규정 제6조 제2항에 따라 ±5% 오차 미적용
    sugar_brix_guarantee: Optional[float]  # 당도 보장 브릭스 (None이면 미표기 라인)
    has_sugar_guarantee: bool  # 당도 보장 여부 (False이면 규정 제7조 제3항에 따라 당도 미달 하자 적용 제외)
    description: str


OFFICIAL_PRODUCTS: Dict[str, OfficialProductSKU] = {
    "WTM-SEL-8": OfficialProductSKU(
        sku="WTM-SEL-8",
        name="제주 교동마을 노지 당도선별 수박 8kg 이상 1통",
        price=27900,
        shipping_fee=4000,
        spec_description="8kg 이상 1통",
        weight_kg=8.0,
        is_min_spec=True,  # 규정 제6조 제2항: 8kg 이상 규격 상품은 ±5% 허용오차 절대 미적용 (7.9kg도 규격 미달 하자)
        sugar_brix_guarantee=11.0,  # 규정 제7조 제2항 제1호: 수박 11브릭스 이상 보장
        has_sugar_guarantee=True,
        description="제주 교동마을 노지 당도선별 수박 8kg 이상 (11브릭스 이상 당도선별 보장, 규격 표기 상품으로 허용오차 없음)",
    ),
    "HGL-SEL-5": OfficialProductSKU(
        sku="HGL-SEL-5",
        name="제주 하우스 감귤 당도선별 5kg",
        price=30000,
        shipping_fee=4000,
        spec_description="5kg",
        weight_kg=5.0,
        is_min_spec=False,  # 일반 5kg 표기 상품: 규정 제6조 제1항에 따라 ±5% 허용오차 적용 (4.75kg 이상 정상)
        sugar_brix_guarantee=12.0,  # 규정 제7조 제2항 제2호: 하우스감귤 12브릭스 이상 보장
        has_sugar_guarantee=True,
        description="제주 하우스 감귤 당도선별 5kg (12브릭스 이상 당도선별 보장, 일반 중량 상품으로 ±5% 허용오차 적용)",
    ),
    "HGL-STD-5": OfficialProductSKU(
        sku="HGL-STD-5",
        name="제주 하우스 감귤 5kg",
        price=24000,
        shipping_fee=4000,
        spec_description="5kg",
        weight_kg=5.0,
        is_min_spec=False,  # 일반 5kg 표기 상품: 규정 제6조 제1항에 따라 ±5% 허용오차 적용
        sugar_brix_guarantee=None,  # 당도 미표기 라인
        has_sugar_guarantee=False,  # 규정 제7조 제3항: 당도 미표기 라인은 당도 미달 하자 적용 제외!
        description="제주 하우스 감귤 5kg (당도 미표기 표준 라인, 규정 제7조 제3항에 따라 당도 미달 하자 적용 제외)",
    ),
}


def get_official_product(sku_code: str) -> Optional[OfficialProductSKU]:
    """SKU 코드로 공식 판매 상품 정보를 조회합니다."""
    if not sku_code:
        return None
    return OFFICIAL_PRODUCTS.get(sku_code.upper().strip())


def evaluate_product_sugar_claim(sku_code: str, measured_brix: float) -> Dict[str, Any]:
    """공식 상품의 당도 미달 클레임을 규정 제7조에 따라 판정합니다."""
    prod = get_official_product(sku_code)
    if not prod:
        return {
            "sku": sku_code,
            "valid_sku": False,
            "is_defect": False,
            "verdict": "미등록 상품",
            "reason": f"'{sku_code}'는 등록되지 않은 SKU 코드입니다.",
        }

    if not prod.has_sugar_guarantee or prod.sugar_brix_guarantee is None:
        return {
            "sku": prod.sku,
            "name": prod.name,
            "valid_sku": True,
            "has_guarantee": False,
            "is_defect": False,
            "guaranteed_brix": None,
            "measured_brix": measured_brix,
            "verdict": "하자 적용 제외",
            "reason": "[규정 제7조 제3항] 당도 보장 표기가 없는 라인(HGL-STD-5 등)은 애초에 약속한 수치가 없으므로, 로트 기록상 당도가 낮게 나오더라도 하자로 판정되지 아니합니다.",
            "action": "정상 상품 안내 (당도 미달 하자 적용 제외)",
        }

    if measured_brix < prod.sugar_brix_guarantee:
        return {
            "sku": prod.sku,
            "name": prod.name,
            "valid_sku": True,
            "has_guarantee": True,
            "is_defect": True,
            "guaranteed_brix": prod.sugar_brix_guarantee,
            "measured_brix": measured_brix,
            "verdict": "당도 미달 하자",
            "reason": f"[규정 제7조 제2항] {prod.name}의 보장 당도는 {prod.sugar_brix_guarantee}브릭스 이상이며, 측정 당도({measured_brix}Bx)가 기준에 미달합니다.",
            "action": "재배송 처리 (재배송분도 미달 시 전액환불 및 쿠폰/적립금 보상)",
        }
    else:
        return {
            "sku": prod.sku,
            "name": prod.name,
            "valid_sku": True,
            "has_guarantee": True,
            "is_defect": False,
            "guaranteed_brix": prod.sugar_brix_guarantee,
            "measured_brix": measured_brix,
            "verdict": "정상 당도 충족",
            "reason": f"[규정 제7조] 보장 당도 {prod.sugar_brix_guarantee}브릭스 이상을 충족합니다 ({measured_brix}Bx).",
            "action": "정상 안내",
        }


def evaluate_product_weight_claim(sku_code: str, measured_weight_kg: float) -> Dict[str, Any]:
    """공식 상품의 중량/규격 미달 클레임을 규정 제6조에 따라 판정합니다."""
    prod = get_official_product(sku_code)
    if not prod:
        return {
            "sku": sku_code,
            "valid_sku": False,
            "is_defect": False,
            "verdict": "미등록 상품",
            "reason": f"'{sku_code}'는 등록되지 않은 SKU 코드입니다.",
        }

    if prod.is_min_spec:
        # 규격 표기 상품 ("~이상"): ±5% 허용오차 절대 미적용 (규정 제6조 제2항)
        if measured_weight_kg < prod.weight_kg:
            shortfall = round(prod.weight_kg - measured_weight_kg, 2)
            return {
                "sku": prod.sku,
                "name": prod.name,
                "valid_sku": True,
                "is_min_spec": True,
                "is_defect": True,
                "target_weight_kg": prod.weight_kg,
                "measured_weight_kg": measured_weight_kg,
                "tolerance_pct": 0.0,
                "shortfall_kg": shortfall,
                "verdict": "규격 미달 하자",
                "reason": f"[규정 제6조 제2항] '{prod.spec_description}' 표기 규격 상품은 ±5% 허용오차를 절대 적용하지 아니하므로, {measured_weight_kg}kg은 규격 미달 하자에 해당합니다.",
                "action": "부족분 부분환불 또는 재배송 중 고객 선택",
            }
        else:
            return {
                "sku": prod.sku,
                "name": prod.name,
                "valid_sku": True,
                "is_min_spec": True,
                "is_defect": False,
                "target_weight_kg": prod.weight_kg,
                "measured_weight_kg": measured_weight_kg,
                "tolerance_pct": 0.0,
                "shortfall_kg": 0.0,
                "verdict": "정상 규격 충족",
                "reason": f"기준 규격({prod.weight_kg}kg 이상)을 충족합니다 ({measured_weight_kg}kg).",
                "action": "정상 안내",
            }
    else:
        # 일반 중량 표기 상품: ±5% 허용오차 적용 (규정 제6조 제1항)
        threshold = round(prod.weight_kg * 0.95, 2)
        if measured_weight_kg < threshold:
            shortfall = round(prod.weight_kg - measured_weight_kg, 2)
            return {
                "sku": prod.sku,
                "name": prod.name,
                "valid_sku": True,
                "is_min_spec": False,
                "is_defect": True,
                "target_weight_kg": prod.weight_kg,
                "measured_weight_kg": measured_weight_kg,
                "tolerance_pct": 5.0,
                "threshold_kg": threshold,
                "shortfall_kg": shortfall,
                "verdict": "무게 미달 하자",
                "reason": f"[규정 제6조 제1항] 일반 표기 무게 상품의 허용오차는 ±5%이며, 기준선({threshold}kg) 미만이므로 무게 미달 하자에 해당합니다.",
                "action": "부족분 부분환불 또는 재배송 중 고객 선택",
            }
        else:
            return {
                "sku": prod.sku,
                "name": prod.name,
                "valid_sku": True,
                "is_min_spec": False,
                "is_defect": False,
                "target_weight_kg": prod.weight_kg,
                "measured_weight_kg": measured_weight_kg,
                "tolerance_pct": 5.0,
                "threshold_kg": threshold,
                "shortfall_kg": 0.0,
                "verdict": "정상 허용오차 범위 내",
                "reason": f"[규정 제6조 제1항] 일반 표기 무게의 ±5% 허용오차({threshold}kg 이상) 범위 내 정상 상품입니다 ({measured_weight_kg}kg).",
                "action": "정상 안내",
            }


# ==============================================================================
# 18. 결제·주문 대사 절차 및 10대 불일치 처리 기준 (M-01 ~ M-10)
# ==============================================================================

class ReconciliationCode(str, Enum):
    """결제·주문 대사 10대 불일치 코드"""

    M_01 = "M-01"  # 네 키 전부 일치 · 주문 레코드 없음/생성 실패 -> 주문 유실 -> 주문 복구 우선 (§4)
    M_02 = "M-02"  # 네 키 전부 일치 · 주문이 취소 상태 -> 취소 처리 및 환불 확인
    M_03 = "M-03"  # 승인번호 없음 (결제 승인 자체가 없음) -> 결제 미완료/타사 결제 -> 결제사 조회 접수 (결제사실 부정 금지)
    M_04 = "M-04"  # 승인번호 일치 · 금액 불일치 -> 부분취소·분할·차액 확인
    M_05 = "M-05"  # 승인시각 ±5분 초과 -> 다른 주문 가능성 -> 인접 주문 재대조 (확정 전 복구·환불 금지)
    M_06 = "M-06"  # 카드 뒷 4자리 불일치 -> 타인 결제 가능성 -> 본인확인 후 진행 (명의 확인 전 처리 금지)
    M_07 = "M-07"  # 동일 승인번호 2건 이상 -> 결제사 중복 전송 -> 1건 유지, 나머지 승인 취소
    M_08 = "M-08"  # 주문 1건 · 결제 승인 2건 -> 중복 결제 (승인 2건일 때만 성립) -> 초과분 환불
    M_09 = "M-09"  # 네 키 일치하나 일시적 미조회(반영 지연) -> 시스템 반영 대기 -> 유실 아님! 즉시 환불/복구 금지, 재조회
    M_10 = "M-10"  # 네 키 일치하나 다른 계정에 있음 -> 계정 귀속 문제 -> 계정 명의 확인 후 본인 건만 처리, 타 계정 비공개


@dataclass(frozen=True)
class ReconciliationRule:
    """결제·주문 대사 불일치 코드별 판정 및 처리 지침"""

    code: ReconciliationCode
    mismatch_type: str
    verdict: str
    action_guideline: str
    prohibited_action: str
    guide_script: Optional[str] = None


