# 교동마을 농산 시즌 캘린더 (기준일: 2037-06-30 정본)
# docs/source_materials/agricultural_season_calendar.xlsx 기반
# ==============================================================================


class SeasonStatus(str, Enum):
    """농산 시즌 상태 구분 (교동마을 농산 시즌 캘린더 §2)

    종과 전은 판정(판매 안 함)이 같고 안내 문안만 다르다.
    종료 후 다음 시즌 개시 1개월 전까지는 종, 개시 1개월 전부터 전, 예약을 여는 달은 예로 표기한다.
    """

    BEFORE = "BEFORE"  # 전: 출하 전 — 올해 시즌 개시 직전(개시 1개월 전 구간), 판매 안 함
    RESERVATION = "RESERVATION"  # 예: 예약 접수 — 선접수를 여는 달. 접수와 출고 시점 분리, 예약만
    EARLY = "EARLY"  # 초: 초입 — 출하 시작. 물량이 적고 가격이 높다, 판매 함
    PEAK = "PEAK"  # 성: 성수기 — 물량·품질이 가장 안정, 판매 함
    LATE = "LATE"  # 말: 시즌 말 — 품질 편차가 커진다(장마·노화·저장분), 판매 함
    CLOSED = "CLOSED"  # 종: 종료 — 올해 출하가 끝났거나 아직 사이클 밖, 판매 안 함

    @property
    def code(self) -> str:
        """한글 약칭 (전, 예, 초, 성, 말, 종)"""
        mapping = {
            SeasonStatus.BEFORE: "전",
            SeasonStatus.RESERVATION: "예",
            SeasonStatus.EARLY: "초",
            SeasonStatus.PEAK: "성",
            SeasonStatus.LATE: "말",
            SeasonStatus.CLOSED: "종",
        }
        return mapping[self]

    @property
    def label(self) -> str:
        """한글 상태 명칭"""
        mapping = {
            SeasonStatus.BEFORE: "출하 전",
            SeasonStatus.RESERVATION: "예약 접수",
            SeasonStatus.EARLY: "초입",
            SeasonStatus.PEAK: "성수기",
            SeasonStatus.LATE: "시즌 말",
            SeasonStatus.CLOSED: "종료",
        }
        return mapping[self]

    @property
    def is_sellable(self) -> bool:
        """현재 즉시 일반 판매 가능 여부"""
        return self in (SeasonStatus.EARLY, SeasonStatus.PEAK, SeasonStatus.LATE)

    @property
    def is_reservation_only(self) -> bool:
        """예약 접수 전용 여부"""
        return self == SeasonStatus.RESERVATION

    @classmethod
    def from_code(cls, code: str) -> SeasonStatus:
        """한글 약칭 코드로부터 SeasonStatus 생성"""
        code_map = {
            "전": cls.BEFORE,
            "예": cls.RESERVATION,
            "초": cls.EARLY,
            "성": cls.PEAK,
            "말": cls.LATE,
            "종": cls.CLOSED,
        }
        if code in code_map:
            return code_map[code]
        raise ValueError(f"유효하지 않은 시즌 상태 코드: {code}")


