def get_agri_season_line(crop_or_line: str) -> Optional[AgriSeasonLine]:
    """품목명, 라인 코드, 또는 별칭으로부터 해당 AgriSeasonLine을 조회합니다."""
    key = crop_or_line.strip()
    key_upper = key.upper()

    # 1. 코드 직접 일치
    if key_upper in AGRI_SEASON_LINES:
        return AGRI_SEASON_LINES[key_upper]

    # 2. 청귤 우선 분기 ("청귤"이 포함되면 NGL_RSV, "노지감귤"이나 일반 감귤은 NGL/HGL)
    if "청귤" in key or "풋귤" in key:
        return AGRI_SEASON_LINES["NGL_RSV"]
    if "하우스" in key and ("귤" in key or "감귤" in key):
        return AGRI_SEASON_LINES["HGL"]

    # 3. 별칭 검색
    for line in AGRI_SEASON_LINES.values():
        if key == line.crop_name or key in line.aliases:
            return line
        for alias in line.aliases:
            if key in alias or alias in key:
                return line

    return None


def get_agri_season_status(crop_or_line: str, month: int) -> SeasonStatus:
    """해당 품목의 특정 월(1~12) 시즌 상태를 반환합니다."""
    line = get_agri_season_line(crop_or_line)
    if not line:
        raise ValueError(f"존재하지 않거나 지원되지 않는 농산 품목 라인입니다: {crop_or_line}")
    if month < 1 or month > 12:
        raise ValueError(f"유효하지 않은 월: {month} (1~12 범위만 가능)")
    return line.monthly_statuses[month]


def get_current_season_status(
    crop_or_line: str, target_date: Optional[date] = None
) -> SeasonStatus:
    """기준일(기본값 2037-06-30) 기준 품목의 시즌 상태를 반환합니다."""
    if target_date is None:
        target_date = date(2037, 6, 30)
    return get_agri_season_status(crop_or_line, target_date.month)


def get_active_lines_in_month(
    month: int, statuses: Optional[List[SeasonStatus]] = None
) -> List[AgriSeasonLine]:
    """특정 월에 지정된 상태(기본값: 초입 또는 성수기)인 라인 목록을 반환합니다. 대안 라인 추천에 활용."""
    if statuses is None:
        statuses = [SeasonStatus.EARLY, SeasonStatus.PEAK]
    result = []
    for line in AGRI_SEASON_LINES.values():
        if line.monthly_statuses.get(month) in statuses:
            result.append(line)
    return result


def is_summer_house_citrus_normal(month: int = 6) -> bool:
    """여름철 하우스감귤 출하가 정상인지 판정합니다 (§5 규칙 ⑨). 6~8월 성수기 정상."""
    line = AGRI_SEASON_LINES["HGL"]
    status = line.monthly_statuses.get(month)
    return status in (SeasonStatus.EARLY, SeasonStatus.PEAK)


def check_season_closed_forbidden_words(response_text: str) -> bool:
    """
    상태가 '종'(시즌 종료)일 때 '품절' 단정 표현이 포함되어 있는지 검사합니다 (§5 규칙 ①).
    - 금지어: "품절이라 곧 들어와요", "품절입니다", "품절되어서", "품절되었"
    - "품절이 아니라 시즌이 끝났습니다" 등 정정 표현은 허용.
    """
    # 허용 패턴: "품절이 아니라", "품절 아니라", "품절이 아닌"
    allowed_pattern = r"품절(이\s*아니|이\s*아닌|이\s*아님|아니)"
    clean_text = re.sub(allowed_pattern, "", response_text)

    # 금지 패턴: 단독 품절 표현 또는 "품절이라 곧"
    forbidden_patterns = [
        r"품절이라\s*곧",
        r"품절입니다",
        r"품절되어서",
        r"품절되어",
        r"품절됐",
        r"품절되었",
        r"현재\s*품절",
    ]
    for pattern in forbidden_patterns:
        if re.search(pattern, clean_text):
            return True
    return False


def evaluate_season_inquiry(
    crop_or_line: str,
    query_type: str = "availability",
    target_date: Optional[date] = None,
) -> Dict[str, Any]:
    """
    농산 시즌 캘린더 문의에 대해 10대 업무 처리 기준(§5)에 입각한 정책 및 가이드라인을 판정합니다.

    - query_type:
        - "availability": 현재 출하/구매 가능 여부 문의
        - "when": 언제 들어오는지 입고 시기 문의
        - "early_harvest": 덜 익은 것 조기 출하 요구
        - "discount_request": 다른 시즌 가격 근거 할인 요구
        - "summer_citrus": 여름철 감귤 사진/주문 진위 문의
        - "out_of_season_storage": 시즌 밖 기수령 상품 보관/안전 문의
    """
    if target_date is None:
        target_date = date(2037, 6, 30)

    month = target_date.month
    line = get_agri_season_line(crop_or_line)

    if not line:
        return {
            "handled": False,
            "reason": f"'{crop_or_line}'은 교동마을 11개 농산 라인에 해당하지 않습니다.",
        }

    status = line.monthly_statuses[month]
    status_info = SEASON_STATUS_DEFINITIONS[status]

    result: Dict[str, Any] = {
        "handled": True,
        "line_code": line.line_code,
        "line_name": line.line_name,
        "crop_name": line.crop_name,
        "target_month": month,
        "status": status,
        "status_code": status.code,
        "status_name": status.label,
        "is_sellable": status.is_sellable,
        "is_reservation_only": status.is_reservation_only,
        "next_season_start": line.next_season_start,
        "variance_factors": line.variance_factors,
    }

    # 2. "언제 들어와요" 문의 (§5 규칙 ②)
    if query_type == "when":
        result.update(
            {
                "rule_no": 2,
                "guide_message": f"캘린더는 월 단위 관리 자료이므로 개시 월인 {line.next_season_start}까지만 안내합니다.",
                "restriction": "개별 주문의 확정 입고일·도착일 약속 절대 금지",
            }
        )
        return result

    # 3. 조기 출하 요구 (§5 규칙 ③)
    if query_type == "early_harvest" and status in (SeasonStatus.BEFORE, SeasonStatus.CLOSED):
        result.update(
            {
                "rule_no": 3,
                "action": "조기 출하 거절 안내",
                "guide_message": "시기 외 임의 수확 및 출하는 엄격한 품질 기준상 불가하며, 미숙 개체를 골라 보내드리는 것 또한 불가합니다.",
                "restriction": '"덜 익은 것 골라서" 접수 절대 금지',
            }
        )
        return result

    # 8. 다른 시즌 가격 근거 할인 요구 (§5 규칙 ⑧)
    if query_type == "discount_request":
        result.update(
            {
                "rule_no": 8,
                "action": "할인 불가 및 표기 가격 유지 안내",
                "guide_message": f"같은 {line.crop_name}이라도 재배 방식(하우스는 난방·관리 부하 발생) 및 시즌에 따라 별도 원가 구조를 가집니다. 표기 가격을 유지하며 정상 프로모션 범위 내에서만 안내합니다.",
                "restriction": "임의 할인 및 지난 시즌 가격 약속 절대 금지",
            }
        )
        return result

    # 9. 계절상 성립하지 않아 보이는 사진/주문 문의 (§5 규칙 ⑨)
    if query_type == "summer_citrus" or (line.line_code == "HGL" and month in (6, 7, 8) and query_type != "availability"):
        result.update(
            {
                "rule_no": 9,
                "is_summer_citrus_normal": True,
                "action": "하우스 시설 재배 정상 출하 안내",
                "guide_message": "하우스감귤은 시설 난방 재배로 6~8월 여름철이 가장 물량과 품질이 안정한 성수기입니다. 정상 주문 및 정상 출하 상품입니다.",
                "restriction": "계절만 보고 오배송·사칭으로 임의 단정 절대 금지",
            }
        )
        return result

    # 10. 시즌 밖 저장 품목 보관/안전 문의 (§5 규칙 ⑩)
    if query_type == "out_of_season_storage":
        result.update(
            {
                "rule_no": 10,
                "action": "보관 및 섭취 안전 안내 제공",
                "guide_message": f"시즌 종료는 신규 주문을 받지 못한다는 의미이며, 이미 수령하신 {line.crop_name}의 보관법 및 섭취 안전 안내는 그대로 성심껏 제공합니다.",
                "storage_guidance": line.variance_factors,
                "restriction": '"지금은 시즌이 아니라 확인이 어렵습니다" 식의 응대 거절 절대 금지',
            }
        )
        return result

    # 1. 상태가 종인 라인을 찾는 문의 (§5 규칙 ①)
    if status == SeasonStatus.CLOSED:
        active_lines = get_active_lines_in_month(month)
        alt_names = [al.crop_name for al in active_lines]
        result.update(
            {
                "is_closed": True,
                "rule_no": 1,
                "guide_message": f"품절이 아니라 시즌이 끝났습니다. 다음 시즌은 {line.next_season_start}입니다.",
                "prohibit_sold_out_phrase": True,
                "action": "시즌 밖 안내 + 차기 시즌 개시 월 안내 + 알림 등록 + 대안 제시",
                "recommended_alternatives": alt_names,
                "restriction": '"품절이라 곧 들어와요" 등 단순 품절 단정 표현 절대 금지',
            }
        )
        return result

    # 4. 예약 라인 (§5 규칙 ④)
    if status == SeasonStatus.RESERVATION:
        result.update(
            {
                "rule_no": 4,
                "action": "예약 접수 진행 안내",
                "guide_message": f"현재 예약 접수 중이며, 출고는 {line.next_season_start} 수확 및 숙도 도달 후부터 시작됩니다.",
                "restriction": "출고일 확정 표현 절대 금지",
            }
        )
        return result

    # 기본 응대 (초입, 성수기, 시즌 말)
    result.update(
        {
            "action": f"{status_info.name} 상품 정상 안내",
            "guide_message": status_info.guide_standard if status_info.guide_standard != "—" else "현재 최상의 물량과 품질로 출하 중입니다.",
        }
    )
    return result


# ==============================================================================
# 20. 갯마을 수산 성어기·냉동 공급표 (홍이장 기준일 2037-06-30)
# ==============================================================================

@dataclass
class SeafoodSeasonLine:
    """수산 품목별 월별 성어기·공급 라인 모델 (수산물에는 '종' 부재 원칙)"""
    line_name: str
    item_name: str
    line_code: str
    monthly_statuses: Dict[int, SeasonStatus]
    next_season_start: str
    harvest_interval: str
    variance_factors: str
    aliases: List[str]


SEAFOOD_SEASON_LINES: Dict[str, SeafoodSeasonLine] = {
    "GAL": SeafoodSeasonLine(
        line_name="갈치 (위탁·냉동) GAL",
        item_name="갈치",
        line_code="GAL",
        monthly_statuses={
            1: SeasonStatus.LATE,
            2: SeasonStatus.LATE,
            3: SeasonStatus.LATE,
            4: SeasonStatus.LATE,
            5: SeasonStatus.LATE,
            6: SeasonStatus.LATE,
            7: SeasonStatus.EARLY,
            8: SeasonStatus.PEAK,
            9: SeasonStatus.PEAK,
            10: SeasonStatus.PEAK,
            11: SeasonStatus.PEAK,
            12: SeasonStatus.LATE,
        },
        next_season_start="7월 (성어기 8~11월)",
        harvest_interval="조업일 단위 — 조업 가능 여부가 시즌보다 앞선다",
        variance_factors="기상특보·조업 중단 시 일시 품절. 냉동 재고로 판매는 유지된다",
        aliases=["갈치", "은갈치", "제주 은갈치", "당일바리", "GAL"],
    ),
    "OKD": SeafoodSeasonLine(
        line_name="옥돔 (위탁·냉동) OKD",
        item_name="옥돔",
        line_code="OKD",
        monthly_statuses={
            1: SeasonStatus.PEAK,
            2: SeasonStatus.PEAK,
            3: SeasonStatus.LATE,
            4: SeasonStatus.LATE,
            5: SeasonStatus.LATE,
            6: SeasonStatus.LATE,
            7: SeasonStatus.LATE,
            8: SeasonStatus.LATE,
            9: SeasonStatus.EARLY,
            10: SeasonStatus.PEAK,
            11: SeasonStatus.PEAK,
            12: SeasonStatus.PEAK,
        },
        next_season_start="9월 (성어기 10~2월)",
        harvest_interval="조업일 단위 — 조업 가능 여부가 시즌보다 앞선다",
        variance_factors="연중 냉동 원물만 취급한다. 9월 초입(초), 10~2월 성어기(성), 3~8월 냉동 공급(말)",
        aliases=["옥돔", "제주 옥돔", "냉동 옥돔", "OKD"],
    ),
}


def get_seafood_season_status(item_or_code: str, month: int) -> SeasonStatus:
    """수산물(갈치 GAL, 옥돔 OKD)의 특정 월 상태 반환 (수산물 2종에는 '종'이 없고 연중 냉동 공급)"""
    key = item_or_code.strip().upper()
    if key in SEAFOOD_SEASON_LINES:
        line = SEAFOOD_SEASON_LINES[key]
    else:
        line = None
        for sl in SEAFOOD_SEASON_LINES.values():
            if any(alias in item_or_code for alias in sl.aliases):
                line = sl
                break
        if not line:
            line = SEAFOOD_SEASON_LINES["GAL"]
    return line.monthly_statuses.get(month, SeasonStatus.LATE)





